python3 - <<'PY'
import json,subprocess
image='ghcr.io/ggml-org/llama.cpp:server'
out={}
for k,cmd in [('image',['docker','image','inspect',image,'--format','{{json .Config.Entrypoint}}']),('help',['docker','run','--rm',image,'--help'])]:
 try:
  p=subprocess.run(cmd,text=True,capture_output=True,timeout=30)
  value=p.stdout+p.stderr
  out[k]={'exit':p.returncode,'socket_host':'.sock' in value or 'unix socket' in value.lower(),'host_option':'--host' in value,'tail':value[-500:]}
 except Exception as e:out[k]={'error':type(e).__name__+':'+str(e)[:120]}
v=subprocess.run(['gh','api','-X','POST','repos/G-ACE-inc/server-core/issues/10/comments','--input','-','--jq','.html_url'],input=json.dumps({'body':'AI_CORE_LLAMA_UDS_IMAGE_PREFLIGHT\n'+json.dumps(out,ensure_ascii=False)}),text=True,capture_output=True,timeout=20)
print('PROBE='+json.dumps({k:{name:val for name,val in q.items() if name!='tail'} for k,q in out.items()}))
print('RECEIPT='+v.stdout.strip() if v.returncode==0 else 'UNAVAILABLE')
raise SystemExit(0 if v.returncode==0 and out.get('help',{}).get('exit')==0 else 1)
PY
